const Imap = require('imap');

// Исходные данные
const imapConfig = {
  user: item.json.data.imap_user,
  password: item.json.data.imap_pass,
  host: item.json.data.imap_host,
  port: item.json.data.imap_port,
  tls: true,
};

const sourceFolder = item.json.data.folder;
const uid = item.json.data.uid;
const targetFolder = item.json.target_folder;

const imap = new Imap(imapConfig);

// Функция для задержки
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function openBox(folderName) {
  return new Promise((resolve, reject) => {
    imap.openBox(folderName, false, (err) => {
      if (err) reject(err);
      else resolve();
    });
  });
}

function moveEmail(uid, destination) {
  return new Promise((resolve, reject) => {
    imap.move(uid, destination, (err) => {
      if (err) reject(err);
      else resolve();
    });
  });
}

async function connectImap() {
  return new Promise((resolve, reject) => {
    imap.once('ready', () => resolve());
    imap.once('error', reject);
    imap.connect();
  });
}

async function attemptMove() {
  let lastError = null;
  const maxAttempts = 3;
  const retryDelay = 5000; // 5 секунд

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      console.log(`Попытка перемещения письма ${uid} (попытка ${attempt}/${maxAttempts})`);

      // Подключаемся к IMAP серверу
      await connectImap();

      // Открываем исходную папку
      await openBox(sourceFolder);

      // Перемещаем письмо
      await moveEmail(uid, targetFolder);

      // Закрываем соединение
      imap.end();

      console.log(`Письмо успешно перемещено с ${attempt} попытки`);
      return true;

    } catch (err) {
      console.log(`Ошибка при попытке ${attempt}:`, err.message);
      lastError = err;

      // Если это не последняя попытка, ждем 5 секунд перед следующей
      if (attempt < maxAttempts) {
        console.log(`Ждем ${retryDelay/1000} секунд перед следующей попыткой...`);
        await delay(retryDelay);
      }

      // Закрываем соединение в случае ошибки
      if (imap && imap.state !== 'disconnected') {
        imap.end();
      }
    }
  }

  // Если все попытки неуспешны
  throw new Error(`Не удалось переместить письмо после ${maxAttempts} попыток. Последняя ошибка: ${lastError?.message || 'неизвестная ошибка'}`);
}

// 🔁 Выполнение с 3 попытками
try {
  await attemptMove();
  item.json.data.folder = targetFolder;
  item.json.data.moved = true;
  item.json.data.attempts = "Успешно перемещено";
} catch (err) {
  item.json.data.folder = sourceFolder; // Оставляем в исходной папке
  item.json.data.moved = false;
  item.json.data.error = err.message;
  item.json.data.attempts = "Все попытки неудачны";
}

return item.json.data;

